const source = "// vgsl-module: F:\\avishkarai2\\components\\hero\\triangle-led-front\\shaders\\direct-triangle-raycast.wgsl\nstruct _vgsl_5270f21f__Config {\n  tri_a_b: vec4f,\n  tri_c_target: vec4f,\n  size_steps: vec4f,\n  params: vec4f,\n  target_info: vec4f,\n};\n\n@group(0) @binding(0) var<uniform> cfg: _vgsl_5270f21f__Config;\n@group(0) @binding(1) var light_sources_tex: texture_2d<f32>;\n\nstruct _vgsl_5270f21f__VSOut { @builtin(position) pos: vec4f };\nstruct _vgsl_5270f21f__Interval { start: f32, length: f32, valid: bool };\nstruct _vgsl_5270f21f__TraceHit { rgb: vec3f, distance: f32, hit: bool };\n\nconst _vgsl_5270f21f__MAX_RAYS: u32 = 24u;\n// Jitter amplitude as a fraction of one stratum width. 1.0 = full-width: adjacent\n// strata can swap which discrete LED they sample, maximizing per-pixel variance (the\n// clumpy chroma/luma noise at low ray counts). The half-res→full cubic upsample\n// already protects against banding, so we attenuate the jitter and let regular\n// stratification carry the signal — each ray stays near its stratum center and\n// randomization only dithers residual stratum boundaries.\nconst _vgsl_5270f21f__JITTER_AMPLITUDE: f32 = 0.7;\nconst _vgsl_5270f21f__PI: f32 = 3.141592653589793;\nconst _vgsl_5270f21f__EPSILON: f32 = 1e-5;\n\n@vertex fn vs_main(@builtin(vertex_index) vi: u32) -> _vgsl_5270f21f__VSOut {\n  var p = array<vec2f, 3>(vec2f(-1.0, -3.0), vec2f(-1.0, 1.0), vec2f(3.0, 1.0));\n  var out: _vgsl_5270f21f__VSOut;\n  out.pos = vec4f(p[vi], 0.0, 1.0);\n  return out;\n}\n\nfn _vgsl_5270f21f__tri_a() -> vec2f { return cfg.tri_a_b.xy; }\nfn _vgsl_5270f21f__tri_b() -> vec2f { return cfg.tri_a_b.zw; }\nfn _vgsl_5270f21f__tri_c() -> vec2f { return cfg.tri_c_target.xy; }\n\nfn _vgsl_5270f21f__cross2(a: vec2f, b: vec2f) -> f32 {\n  return a.x * b.y - a.y * b.x;\n}\n\nfn _vgsl_5270f21f__wrap_pi(angle: f32) -> f32 {\n  return atan2(sin(angle), cos(angle));\n}\n\nfn _vgsl_5270f21f__triangle_signed_area(a: vec2f, b: vec2f, c: vec2f) -> f32 {\n  return _vgsl_5270f21f__cross2(b - a, c - a);\n}\n\nfn _vgsl_5270f21f__point_in_triangle(p: vec2f, a: vec2f, b: vec2f, c: vec2f) -> bool {\n  let area = _vgsl_5270f21f__triangle_signed_area(a, b, c);\n  if (abs(area) <= _vgsl_5270f21f__EPSILON) {\n    return false;\n  }\n  let inv_area = 1.0 / area;\n  let u = _vgsl_5270f21f__cross2(b - p, c - p) * inv_area;\n  let v = _vgsl_5270f21f__cross2(c - p, a - p) * inv_area;\n  let w = 1.0 - u - v;\n  return u >= -_vgsl_5270f21f__EPSILON && v >= -_vgsl_5270f21f__EPSILON && w >= -_vgsl_5270f21f__EPSILON;\n}\n\nfn _vgsl_5270f21f__segment_distance(p: vec2f, a: vec2f, b: vec2f) -> f32 {\n  let e = b - a;\n  let v = p - a;\n  let h = clamp(dot(v, e) / max(dot(e, e), _vgsl_5270f21f__EPSILON), 0.0, 1.0);\n  return length(v - e * h);\n}\n\nfn _vgsl_5270f21f__triangle_edge_distance(p: vec2f, a: vec2f, b: vec2f, c: vec2f) -> f32 {\n  return min(\n    _vgsl_5270f21f__segment_distance(p, a, b),\n    min(_vgsl_5270f21f__segment_distance(p, b, c), _vgsl_5270f21f__segment_distance(p, c, a)),\n  );\n}\n\nfn _vgsl_5270f21f__angular_interval(p: vec2f, a: vec2f, b: vec2f, c: vec2f) -> _vgsl_5270f21f__Interval {\n  if (abs(_vgsl_5270f21f__triangle_signed_area(a, b, c)) <= _vgsl_5270f21f__EPSILON) {\n    return _vgsl_5270f21f__Interval(0.0, 0.0, false);\n  }\n  if (_vgsl_5270f21f__point_in_triangle(p, a, b, c)) {\n    return _vgsl_5270f21f__Interval(0.0, 0.0, false);\n  }\n  if (_vgsl_5270f21f__triangle_edge_distance(p, a, b, c) <= cfg.size_steps.w) {\n    return _vgsl_5270f21f__Interval(0.0, 0.0, false);\n  }\n\n  let center = (a + b + c) / 3.0;\n  let center_angle = atan2(center.y - p.y, center.x - p.x);\n  let ra = _vgsl_5270f21f__wrap_pi(atan2(a.y - p.y, a.x - p.x) - center_angle);\n  let rb = _vgsl_5270f21f__wrap_pi(atan2(b.y - p.y, b.x - p.x) - center_angle);\n  let rc = _vgsl_5270f21f__wrap_pi(atan2(c.y - p.y, c.x - p.x) - center_angle);\n  let min_rel = min(ra, min(rb, rc));\n  let max_rel = max(ra, max(rb, rc));\n  let length = max_rel - min_rel;\n  if (!(length > _vgsl_5270f21f__EPSILON) || length >= _vgsl_5270f21f__PI) {\n    return _vgsl_5270f21f__Interval(0.0, 0.0, false);\n  }\n  return _vgsl_5270f21f__Interval(_vgsl_5270f21f__wrap_pi(center_angle + min_rel), length, true);\n}\n\n// Interleaved gradient noise (Jimenez) → [0,1] with blue-noise-like spectrum: spatially\n// high-frequency, so the per-pixel ray jitter it drives reads as fine grain (not white-noise\n// clumps) and is removed far better by the half-res→full cubic upsample + the floor dither.\nfn _vgsl_5270f21f__ign(p: vec2f) -> f32 {\n  return fract(52.9829189 * fract(dot(p, vec2f(0.06711056, 0.00583715))));\n}\n\nfn _vgsl_5270f21f__load_light_source(sample_pos: vec2f) -> vec4f {\n  let dims = textureDimensions(light_sources_tex);\n  let inside =\n    sample_pos.x >= 0.0 && sample_pos.x < f32(dims.x) &&\n    sample_pos.y >= 0.0 && sample_pos.y < f32(dims.y);\n  if (!inside) {\n    return vec4f(0.0, 0.0, 0.0, 1000.0);\n  }\n  let px = clamp(vec2i(floor(sample_pos)), vec2i(0), vec2i(dims) - vec2i(1));\n  return textureLoad(light_sources_tex, px, 0);\n}\n\n// Per-edge ray/segment invariants that don't change across the ray sweep (they depend only on the\n// pixel origin and the fixed triangle edge): the edge vector, the origin->edge offset, and their\n// 2D cross. Precomputed once per pixel and reused for all MAX_RAYS directions.\nstruct _vgsl_5270f21f__EdgePrecomp { e: vec2f, diff: vec2f, cross_diff_e: f32 };\n\nfn _vgsl_5270f21f__precompute_edge(origin: vec2f, p: vec2f, q: vec2f) -> _vgsl_5270f21f__EdgePrecomp {\n  let e = q - p;\n  let diff = p - origin;\n  return _vgsl_5270f21f__EdgePrecomp(e, diff, _vgsl_5270f21f__cross2(diff, e));\n}\n\n// Closed-form ray (origin + t*dir, t > minStep) vs segment — dir-dependent part only; returns\n// t >= 0 at the hit or -1 (miss/parallel). One reciprocal feeds both t and u.\nfn _vgsl_5270f21f__ray_segment_t(dir: vec2f, pre: _vgsl_5270f21f__EdgePrecomp) -> f32 {\n  let denom = _vgsl_5270f21f__cross2(dir, pre.e);\n  if (abs(denom) < _vgsl_5270f21f__EPSILON) { return -1.0; }\n  let inv = 1.0 / denom;\n  let t = pre.cross_diff_e * inv;\n  let u = _vgsl_5270f21f__cross2(pre.diff, dir) * inv;\n  if (t < cfg.size_steps.z || u < 0.0 || u > 1.0) { return -1.0; }\n  return t;\n}\n\n// Analytic: the LEDs sit on the triangle edges, and angular_interval already aimed this ray\n// into the triangle's arc, so the nearest ray<->edge intersection is the first lit edge it\n// can reach (nearest => the near edge occludes the far edges for free). One sample of the\n// LED color there replaces the SDF sphere-march — no SDF / .w channel needed at all.\nfn _vgsl_5270f21f__trace_light_source(origin: vec2f, dir: vec2f, pre_ab: _vgsl_5270f21f__EdgePrecomp, pre_bc: _vgsl_5270f21f__EdgePrecomp, pre_ca: _vgsl_5270f21f__EdgePrecomp) -> _vgsl_5270f21f__TraceHit {\n  var t = 1e30;\n  let t0 = _vgsl_5270f21f__ray_segment_t(dir, pre_ab);\n  let t1 = _vgsl_5270f21f__ray_segment_t(dir, pre_bc);\n  let t2 = _vgsl_5270f21f__ray_segment_t(dir, pre_ca);\n  if (t0 >= 0.0) { t = min(t, t0); }\n  if (t1 >= 0.0) { t = min(t, t1); }\n  if (t2 >= 0.0) { t = min(t, t2); }\n  if (t > 1e29) { return _vgsl_5270f21f__TraceHit(vec3f(0.0), 0.0, false); }\n\n  let source = _vgsl_5270f21f__load_light_source(origin + dir * t);\n  let source_active = max(max(source.r, source.g), source.b) > cfg.params.w;\n  if (source_active) {\n    return _vgsl_5270f21f__TraceHit(source.rgb, t, true);\n  }\n  return _vgsl_5270f21f__TraceHit(vec3f(0.0), 0.0, false);\n}\n\n@fragment fn fs_main(in: _vgsl_5270f21f__VSOut) -> @location(0) vec4f {\n  let target_scale = max(cfg.target_info.x, 1e-4);\n  let pixel_sim = in.pos.xy / target_scale;\n  let a = _vgsl_5270f21f__tri_a();\n  let b = _vgsl_5270f21f__tri_b();\n  let c = _vgsl_5270f21f__tri_c();\n  let interval = _vgsl_5270f21f__angular_interval(pixel_sim, a, b, c);\n  if (!interval.valid) {\n    return vec4f(0.0, 0.0, 0.0, 1.0);\n  }\n\n  let jitter = (_vgsl_5270f21f__ign(in.pos.xy) - 0.5) * _vgsl_5270f21f__JITTER_AMPLITUDE;\n  // The ray angle is exactly linear in i: angle = interval.start + interval.length * t with\n  // t = (i + 0.5 + jitter) / MAX_RAYS. The closed-form clamp never triggers because jitter ∈\n  // [-0.35, 0.35] (JITTER_AMPLITUDE 0.7) keeps t strictly inside (0, 1) for every i. So sweep\n  // the direction by rotating it one fixed angular step per ray — 2 trig calls per pixel\n  // instead of 2 per ray (MAX_RAYS=24). The hit point (origin + dir*t) is invariant to any\n  // tiny magnitude drift since the ray/segment t absorbs it; only the angle matters, and that\n  // accumulates only ~MAX_RAYS ULP over the sweep.\n  let inv_rays = 1.0 / f32(_vgsl_5270f21f__MAX_RAYS);\n  let step_angle = interval.length * inv_rays;\n  let start_angle = interval.start + interval.length * (0.5 + jitter) * inv_rays;\n  let step_c = cos(step_angle);\n  let step_s = sin(step_angle);\n  var dir = vec2f(cos(start_angle), sin(start_angle));\n  // Hoist the per-edge ray/segment invariants out of the ray loop (origin + edges are fixed).\n  let pre_ab = _vgsl_5270f21f__precompute_edge(pixel_sim, a, b);\n  let pre_bc = _vgsl_5270f21f__precompute_edge(pixel_sim, b, c);\n  let pre_ca = _vgsl_5270f21f__precompute_edge(pixel_sim, c, a);\n  var sum = vec3f(0.0);\n  for (var i = 0u; i < _vgsl_5270f21f__MAX_RAYS; i = i + 1u) {\n    let hit = _vgsl_5270f21f__trace_light_source(pixel_sim, dir, pre_ab, pre_bc, pre_ca);\n    if (hit.hit) {\n      // Geometric spreading on distance NORMALIZED to the scene size (target_info.y =\n      // ref_height / sim_height) so the radiance is resolution-independent — raw sim-px\n      // distance made shorter render targets read brighter/whiter. Beer-Lambert absorption\n      // (params.x already per-sim-height) eats far light through the smoke/atmosphere.\n      let falloff_dist = hit.distance * cfg.target_info.y;\n      let distance_weight =\n        pow(max(falloff_dist, 1.0), -cfg.params.y) * exp(-cfg.params.x * hit.distance);\n      sum += hit.rgb * distance_weight;\n    }\n    // Rotate the direction by one angular step for the next ray.\n    dir = vec2f(dir.x * step_c - dir.y * step_s, dir.x * step_s + dir.y * step_c);\n  }\n\n  // Match the cascade path's directional average semantics: angular sample mean,\n  // independent of ray count. `params.z` remains the visual calibration knob.\n  let radiance = (sum / f32(_vgsl_5270f21f__MAX_RAYS)) * cfg.params.z;\n  return vec4f(radiance, 1.0);\n}\n";
